function showDetail(e){e.stopPropagation();const t=e.currentTarget;const n=document.getElementById("detail-container");if(n.classList.contains("active")){closeDetail();setInfosStatus(t,false);setDefaultOption("action")}else{n.classList.toggle("active")}var o=e.currentTarget.querySelector(".employee-id .id").innerText;getDetail(o).then((function(e){renderDetail(e)})).catch((function(e){console.error("Có lỗi khi lấy chi tiết nhân viên:",e);$("#detail-container tbody").html("<p>Không thể tải thông tin nhân viên.</p>")}));t.parentNode.insertBefore(n,t.nextElementSibling)}function getDetail(e){return new Promise(((t,n)=>{$.ajax({url:"aemployee?a=info&id="+e,type:"POST",dataType:"json",success:function(e){console.log(e);t(e)},error:function(e){n(e)}})}))}function renderDetail(e){const t=document.querySelector("#detail-container");var n=e.user;const o=`\n           <tr class="group">\n                <th scope="row" class="grid-col-1" >\n                    <input type="text" name="eid" value="${e.id}" hidden>\n                    <div class="flex-coll" style="align-items: start">\n                        <div class="form-check">\n                            <input class="form-check-input" type="radio" name="gender" id="exampleRadios1" value="1" checked readonly>\n                            <label class="form-check-label" for="exampleRadios1">\n                                Nam\n                            </label>\n                        </div>\n                        <div class="form-check">\n                            <input class="form-check-input" type="radio" name="gender" id="exampleRadios2" value="2" readonly>\n                            <label class="form-check-label" for="exampleRadios2">\n                                Nữ\n                            </label>\n                        </div>\n                        <div class="form-check">\n                            <input class="form-check-input" type="radio" name="gender" id="exampleRadios3" value="0" readonly>\n                            <label class="form-check-label" for="exampleRadios3">\n                                Ẩn\n                            </label>\n                        </div>\n                    </div>\n                </th>\n                <td class="grid-col-1">\n                    <input class="info-input" type="date" name="dob" value="${n.dob}" readonly>\n                </td>\n                <td class="grid-col-1">\n                    <input class="info-input" type="text" name="phone" value="${n.phone}" readonly>\n                </td>\n                <td class="grid-col-1">\n                    <div class="flex-coll" style="align-items: start;">\n                        <input class="info-input" type="text" name="area" value="${e.area}" readonly>\n                        <input class="info-input" type="text" name="position" value="${e.position}" readonly>\n\n                    </div>\n                </td>\n                <td class="grid-col-1">\n                    <span class="updateAt">${e.updateAt}</span>\n                </td>\n                <td class="grid-col-1">\n                    <span class="dateIn">${n.dateIn}</span>\n                </td>\n\x3c!--                <td class="grid-col-1_5">--\x3e\n\x3c!--                    <div class="flex-coll" style="align-items: end;">--\x3e\n\x3c!--                        <button class="btn btn-primary btn-setupupdate" type="button" onclick="setupUpdate(event);" style="background-color: blue; color:white">Cập nhật</button>--\x3e\n\x3c!--                        <div class="flex-roww secondary-btns-container" style="display: none">--\x3e\n\x3c!--                            <button class="btn btn-fourth btn-save" style="margin-right: 20px;background-color: blue; color:white" type="button" onclick="saveUpdateDetails(event);">Lưu</button>--\x3e\n\x3c!--                            <button class="btn btn-fourth btn-cancel" style="" type="button" onclick="closeDetail();">Hủy</button>--\x3e\n\n\x3c!--                        </div>--\x3e\n\x3c!--                    </div>--\x3e\n\x3c!--                </td>--\x3e\n           </tr>\n             <tr class="edit-tool" style="display: none">\n                 <td colspan="4">\n                    <div class="flex-roww " style="justify-content: space-around;width: 100%;">\n                        <button class="btn btn-outline-primary" onclick="cancelUpdate()">Hủy</button>\n                        <button class="btn btn-primary" onclick="update(${n.id})">Lưu</button>\n                    </div>\n                </td>\n            </tr>\n    `;t.querySelector("#detail-table tbody").innerHTML=o;const a=t.querySelectorAll('input[name="gender"]');a.forEach((e=>{if(e.value==n.gender)e.checked=true;else{e.checked=false;e.closest(".form-check").style.display="none"}}))}function handleChange(e){e.stopPropagation();let t=e.target.value;setDefaultOption("action");e.target.value=t;console.log("selected value: "+t);const n=e.currentTarget.closest(".group");t=t.toUpperCase();switch(t){case"LOCK":{setInfosStatus(n,false);var o=n.querySelector('input[name="name"]').value;var a=n.querySelector(".email").innerText;var l=o+"\n"+a;var r=n.querySelector(".id").innerText;setupConfirm(r,"#lock-confirm-modal",l);break}case"UNLOCK":{setInfosStatus(n,false);var o=n.querySelector('input[name="name"]').value;var r=n.querySelector(".id").innerText;setupConfirm(r,"#unlock-confirm-modal",o);break}case"DELETE":{setInfosStatus(n,false);var o=n.querySelector('input[name="name"]').value;var r=n.querySelector(".id").innerText;setupConfirm(r,"#delete-confirm-modal",o);break}case"PWD":{setInfosStatus(n,false);var o=n.querySelector('input[name="name"]').value;var r=n.querySelector(".id").innerText;setupConfirm(r,"#pwd-confirm-modal",o);break}case"UPDATE":{setInfosStatus(n,false);var r=n.querySelector(".id").innerText;setupUpdate(r,n);break}default:setInfosStatus(n,false)}}function closeModal(e){e.currentTarget.closest(".modall").classList.remove("active")}function lock(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;$.ajax({type:"POST",url:"aemployee?a=lock",data:{id:t},success:function(e){console.log(e);$("#aemployee-response").html(e);hideModal("#lock-confirm-modal");setDefaultOption("action")},error:function(e){$("#aemployee-response").html(e.responseText)}})}function active(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;$.ajax({type:"POST",url:"aemployee?a=active",data:{id:t},success:function(e){$("#aemployee-response").html(e);hideModal("#unlock-confirm-modal");setDefaultOption("action")},error:function(e){$("#aemployee-response").html(e.responseText)}})}function setupConfirm(e,t,n){openModal(t);document.querySelector(t).querySelector(".object").innerText=n;document.querySelector(t).querySelector('input[name="id"]').value=e}function pwd(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;$.ajax({type:"POST",url:"aemployee?a=pwd",data:{id:t},success:function(e){$("#aemployee-response").html(e);hideModal("#pwd-confirm-modal");setDefaultOption("action")},error:function(e){$("#aemployee-response").html(e.responseText)}})}function deleteEmployee(e){var t=e.currentTarget.closest(".group").querySelector('input[name="id"]').value;console.log("xóa: "+t);$.ajax({type:"POST",url:"aemployee?a=delete",data:{id:t},success:function(e){$("#aemployee-response").html(e);hideModal("#delete-confirm-modal")},error:function(e){$("#aemployee-response").html(e.responseText)}})}function setupUpdate(e,t){const n=document.getElementById("detail-container");n.classList.add("active");getDetail(e).then((function(e){renderDetail(e);const t=n.querySelectorAll("input.info-input");t.forEach((function(e){e.readOnly=false}));n.querySelector(".edit-tool").style.display="table-row";const o=n.querySelectorAll('input[name="gender"]');o.forEach((e=>{e.closest(".form-check").style.display="block";e.readOnly=false}))})).catch((function(e){console.error("Có lỗi khi lấy chi tiết khách hàng:",e);$("#detail-container tbody").html("<p>Không thể tải thông tin khách hàng.</p>")}));t.parentNode.insertBefore(n,t.nextElementSibling);const o=t.querySelectorAll("input.info-input");o.forEach((function(e){e.readOnly=false}))}function update(e){console.log(e);const t=document.querySelector(`#employee${e}`);const n=document.querySelector("#detail-container");console.log(t);const o=t.querySelector('input[name="name"]').value;const a=n.querySelector('input[name="gender"]:checked').value;const l=n.querySelector('input[name="dob"]').value;const r=n.querySelector('input[name="phone"]').value;const c=n.querySelector('input[name="position"]').value;const s=n.querySelector('input[name="area"]').value;$.ajax({type:"POST",url:"aemployee?a=update",data:{id:e,name:o,gender:a,dob:l,phone:r,position:c,area:s},success:function(e){$("#aemployee-response").html(e);setInfosStatus(t,false);setInfosStatus(n,false);setDefaultOption("action");closeDetail();hideModal("#delete-confirm-modal")},error:function(e){$("#aemployee-response").html(e.responseText)}})}function closeDetail(){document.querySelector("#detail-container").classList.remove("active")}function add(){const e=document.querySelector("#addEmployeeForm");var t=new FormData(e);var n=t.get("name");var o=t.get("email");var a=t.get("position");var l=t.get("area");var r=t.get("pwd");$.ajax({type:"POST",url:"aemployee?a=add",data:{name:n,position:a,area:l,email:o,pwd:r},success:function(e){console.log(e);$("#aemployee-response").html(e)},error:function(e){$("#aemployee-response").html(e.responseText)}})}function errorEmail(e){const t=document.querySelector("#addEmployeeForm");t.querySelector(".email-error").innerText=e}document.addEventListener("DOMContentLoaded",(function(){document.querySelector("#add-btn").addEventListener("click",(function(e){e.preventDefault();openModal("#add-modal")}))}));function getRoles(e){return new Promise(((t,n)=>{$.ajax({url:e,type:"POST",dataType:"json",success:function(e){console.log(e);t(e)},error:function(e){n(e)}})}))}function showRoles(e){console.log("roles");e.preventDefault();openModal("#roles-modal");var t=e.currentTarget.href;getRoles(t).then((function(e){renderRoles(e)})).catch((function(e){console.error("Có lỗi khi lấy tải quyền truy cập:",e);showErrorToast2("Không thể tải quyền truy cập của tài khoản","none")}))}function renderRoles(e){const t=document.querySelector("#updateRolesForm");var n=e.name;var o=e.email;var a=e.id;var l=e.roles;t.querySelector(".name").innerText=n;t.querySelector(".email").innerText=o;t.querySelector('input[name="id"]').value=a;const r=t.querySelectorAll("input.role");r.forEach((function(e){if(l.includes(e.name)){e.checked=true}e.disabled=true}));t.querySelector(".btn-cancel").style.display="none";t.querySelector(".btn-save").style.display="none";t.querySelector(".btn-setup").style.display="block"}function setupUpdateRoles(e){const t=e.currentTarget.closest(".group");const n=t.querySelectorAll("input");n.forEach((function(e){e.disabled=false}));t.querySelector(".btn-save").style.display="block";t.querySelector(".btn-cancel").style.display="block";t.querySelector(".btn-setup").style.display="none"}function saveRoles(){const e=document.querySelector("#updateRolesForm");var t=e.querySelector("input[name='id']").value;var n=e.querySelector("input[name='employee']").checked?"employee":null;var o=e.querySelector("input[name='customer']").checked?"customer":null;var a=e.querySelector("input[name='product']").checked?"product":null;var l=e.querySelector("input[name='order']").checked?"order":null;$.ajax({type:"POST",url:"aemployee?a=updateRoles",data:{id:t,employee:n,customer:o,product:a,order:l},success:function(e){$("#aemployee-response").html(e);hideModal("#roles-modal")},error:function(e){$("#aemployee-response").html(e.responseText)}})}